# -*- coding: utf-8 -*-
import datetime
import functools
import os


def save_failure_screenshot(target, screenshot_dir=None, prefix="playwright_failure"):
    """Best-effort screenshot helper used by Robot interface decorators."""
    page = _resolve_page(target)
    if page is None:
        return None

    target_dir = screenshot_dir or _resolve_screenshot_dir(target) or os.getcwd()
    if not os.path.exists(target_dir):
        os.makedirs(target_dir)
    filename = "{}_{}.png".format(prefix, datetime.datetime.now().strftime("%Y%m%d_%H%M%S"))
    path = os.path.join(target_dir, filename)
    page.screenshot(path=path, full_page=True)
    return path


def catch_interface_exception(func):
    """Capture screenshot before re-raising keyword failures."""

    @functools.wraps(func)
    def wrapper(self, *args, **kwargs):
        try:
            return func(self, *args, **kwargs)
        except Exception:
            try:
                save_failure_screenshot(self)
            except Exception:
                pass
            raise

    return wrapper


def _resolve_screenshot_dir(target):
    if hasattr(target, "screenshot_dir"):
        return target.screenshot_dir
    if hasattr(target, "_screenshot_dir"):
        return target._screenshot_dir
    return None


def _resolve_page(target):
    if hasattr(target, "page"):
        return target.page
    if hasattr(target, "session") and hasattr(target.session, "page"):
        return target.session.page
    if hasattr(target, "_sessions"):
        try:
            session = target._sessions.get(None)
            if hasattr(session, "page"):
                return session.page
            if hasattr(session, "session") and hasattr(session.session, "page"):
                return session.session.page
        except Exception:
            return None
    return None
